197	    /// Load configuration from environment variables and the database.
198	    ///
199	    /// Priority: env var > TOML config file > DB settings > default.
200	    /// This is the primary way to load config after DB is connected.
201	    pub async fn from_db(
202	        store: &(dyn crate::db::SettingsStore + Sync),
203	        user_id: &str,
204	    ) -> Result<Self, ConfigError> {
205	        Self::from_db_with_toml(store, user_id, None).await
206	    }
207	
208	    /// Load from DB with an optional TOML config file overlay.
209	    pub async fn from_db_with_toml(
210	        store: &(dyn crate::db::SettingsStore + Sync),
211	        user_id: &str,
212	        toml_path: Option<&std::path::Path>,
213	    ) -> Result<Self, ConfigError> {
214	        let _ = dotenvy::dotenv();
215	        crate::bootstrap::load_ironclaw_env();
216	
217	        // Load all settings from DB into a Settings struct
218	        let mut db_settings = match store.get_all_settings(user_id).await {
219	            Ok(map) => Settings::from_db_map(&map),
220	            Err(e) => {
221	                tracing::warn!("Failed to load settings from DB, using defaults: {}", e);
222	                Settings::default()
223	            }
224	        };
225	
226	        // Overlay TOML config file (values win over DB settings)
227	        Self::apply_toml_overlay(&mut db_settings, toml_path)?;
228	
229	        Self::build(&db_settings).await
230	    }
231	
232	    /// Load configuration from environment variables only (no database).
233	    ///
234	    /// Used during early startup before the database is connected,
235	    /// and by CLI commands that don't have DB access.
236	    /// Falls back to legacy `settings.json` on disk if present.
237	    ///
238	    /// Loads both `./.env` (standard, higher priority) and `~/.ironclaw/.env`
239	    /// (lower priority) via dotenvy, which never overwrites existing vars.
240	    pub async fn from_env() -> Result<Self, ConfigError> {
241	        Self::from_env_with_toml(None).await
242	    }
243	
244	    /// Load from env with an optional TOML config file overlay.
245	    pub async fn from_env_with_toml(
246	        toml_path: Option<&std::path::Path>,
247	    ) -> Result<Self, ConfigError> {
248	        let settings = load_bootstrap_settings(toml_path)?;
249	        Self::build(&settings).await
250	    }
251	
252	    /// Load and merge a TOML config file into settings.
253	    ///
254	    /// If `explicit_path` is `Some`, loads from that path (errors are fatal).
255	    /// If `None`, tries the default path `~/.ironclaw/config.toml` (missing
256	    /// file is silently ignored).
257	    fn apply_toml_overlay(
258	        settings: &mut Settings,
259	        explicit_path: Option<&std::path::Path>,
260	    ) -> Result<(), ConfigError> {
261	        let path = explicit_path
262	            .map(std::path::PathBuf::from)
263	            .unwrap_or_else(Settings::default_toml_path);
264	
265	        match Settings::load_toml(&path) {
266	            Ok(Some(toml_settings)) => {
267	                settings.merge_from(&toml_settings);
268	                tracing::debug!("Loaded TOML config from {}", path.display());
269	            }
270	            Ok(None) => {
271	                if explicit_path.is_some() {
272	                    return Err(ConfigError::ParseError(format!(
273	                        "Config file not found: {}",
274	                        path.display()
275	                    )));
276	                }
277	            }
278	            Err(e) => {
279	                if explicit_path.is_some() {
280	                    return Err(ConfigError::ParseError(format!(
281	                        "Failed to load config file {}: {}",
282	                        path.display(),
283	                        e
284	                    )));
285	                }
286	                tracing::warn!("Failed to load default config file: {}", e);
287	            }
288	        }
289	        Ok(())
290	    }
291	
292	    /// Re-resolve only the LLM config after credential injection.
293	    ///
294	    /// Called by `AppBuilder::init_secrets()` after injecting API keys into
295	    /// the env overlay. Only rebuilds `self.llm` — all other config fields
296	    /// are unaffected, preserving values from the initial config load (or
297	    /// from `Config::for_testing()` in test mode).
298	    pub async fn re_resolve_llm(
299	        &mut self,
300	        store: Option<&(dyn crate::db::SettingsStore + Sync)>,
301	        user_id: &str,
302	        toml_path: Option<&std::path::Path>,
303	    ) -> Result<(), ConfigError> {
304	        let settings = if let Some(store) = store {
305	            let mut s = match store.get_all_settings(user_id).await {
306	                Ok(map) => Settings::from_db_map(&map),
307	                Err(_) => Settings::default(),
308	            };
309	            Self::apply_toml_overlay(&mut s, toml_path)?;
310	            s
311	        } else {
312	            Settings::default()
313	        };
314	        self.llm = LlmConfig::resolve(&settings)?;
315	        Ok(())
316	    }
317	
318	    /// Build config from settings (shared by from_env and from_db).
319	    async fn build(settings: &Settings) -> Result<Self, ConfigError> {
320	        let owner_id = resolve_owner_id(settings)?;
321	
322	        let tunnel = TunnelConfig::resolve(settings)?;
323	        let channels = ChannelsConfig::resolve(settings, &owner_id)?;
324	
325	        // Resolve the startup workspace against the durable owner scope. The
326	        // gateway may expose a distinct sender identity, but the base runtime
327	        // workspace stays owner-scoped and per-user gateway workspaces are
328	        // handled separately by WorkspacePool.
329	        let workspace = WorkspaceConfig::resolve(&owner_id)?;
330	
331	        Ok(Self {
332	            owner_id: owner_id.clone(),
333	            database: DatabaseConfig::resolve()?,
334	            llm: LlmConfig::resolve(settings)?,
335	            embeddings: EmbeddingsConfig::resolve(settings)?,
336	            tunnel,
337	            channels,
338	            agent: AgentConfig::resolve(settings)?,
339	            safety: resolve_safety_config(settings)?,
340	            wasm: WasmConfig::resolve(settings)?,
341	            secrets: SecretsConfig::resolve().await?,
342	            builder: BuilderModeConfig::resolve(settings)?,
343	            heartbeat: HeartbeatConfig::resolve(settings)?,
344	            hygiene: HygieneConfig::resolve()?,
345	            routines: RoutineConfig::resolve()?,
346	            sandbox: SandboxModeConfig::resolve(settings)?,
347	            claude_code: ClaudeCodeConfig::resolve(settings)?,
348	            acp: AcpModeConfig::resolve(settings)?,
349	            skills: SkillsConfig::resolve()?,
350	            transcription: TranscriptionConfig::resolve(settings)?,
351	            search: WorkspaceSearchConfig::resolve()?,
352	            workspace,
353	            observability: crate::observability::ObservabilityConfig {
354	                backend: std::env::var("OBSERVABILITY_BACKEND").unwrap_or_else(|_| "none".into()),
355	            },
356	            oauth: OAuthConfig::resolve()?,
357	            relay: RelayConfig::from_env(),
358	        })
359	    }
360	}
