362	pub(crate) fn load_bootstrap_settings(
363	    toml_path: Option<&std::path::Path>,
364	) -> Result<Settings, ConfigError> {
365	    let _ = dotenvy::dotenv();
366	    crate::bootstrap::load_ironclaw_env();
367	
368	    let mut settings = Settings::load();
369	    Config::apply_toml_overlay(&mut settings, toml_path)?;
370	    Ok(settings)
371	}
