373	pub(crate) fn resolve_owner_id(settings: &Settings) -> Result<String, ConfigError> {
374	    let env_owner_id = self::helpers::optional_env("IRONCLAW_OWNER_ID")?;
375	    let settings_owner_id = settings.owner_id.clone();
376	    let configured_owner_id = env_owner_id.clone().or(settings_owner_id.clone());
377	
378	    let owner_id = configured_owner_id
379	        .map(|value| value.trim().to_string())
380	        .filter(|value| !value.is_empty())
381	        .unwrap_or_else(|| "default".to_string());
382	
383	    if owner_id == "default"
384	        && (env_owner_id.is_some()
385	            || settings_owner_id
386	                .as_deref()
387	                .is_some_and(|value| !value.trim().is_empty()))
388	    {
389	        WARNED_EXPLICIT_DEFAULT_OWNER_ID.call_once(|| {
390	            tracing::warn!(
391	                "IRONCLAW_OWNER_ID resolved to the legacy 'default' scope explicitly; durable state will keep legacy owner behavior"
392	            );
393	        });
394	    }
395	
396	    Ok(owner_id)
397	}
