399	/// Load API keys from the encrypted secrets store into a thread-safe overlay.
400	///
401	/// This bridges the gap between secrets stored during onboarding and the
402	/// env-var-first resolution in `LlmConfig::resolve()`. Keys in the overlay
403	/// are read by `optional_env()` before falling back to `std::env::var()`,
404	/// so explicit env vars always win.
405	///
406	/// Also loads tokens from OS credential stores (macOS Keychain / Linux
407	/// credentials files) which don't require the secrets DB.
408	pub async fn inject_llm_keys_from_secrets(
409	    secrets: &dyn crate::secrets::SecretsStore,
410	    user_id: &str,
411	) {
412	    // Static mappings for well-known providers.
413	    // The registry's setup hints define secret_name -> env_var mappings,
414	    // so new providers added to providers.json get injection automatically.
415	    let mut mappings: Vec<(&str, &str)> = vec![
416	        ("llm_nearai_api_key", "NEARAI_API_KEY"),
417	        ("llm_anthropic_oauth_token", "ANTHROPIC_OAUTH_TOKEN"),
418	    ];
419	
420	    // Dynamically discover secret->env mappings from the provider registry.
421	    // Uses selectable() which deduplicates user overrides correctly.
422	    let registry = crate::llm::ProviderRegistry::load();
423	    let dynamic_mappings: Vec<(String, String)> = registry
424	        .selectable()
425	        .iter()
426	        .filter_map(|def| {
427	            def.api_key_env.as_ref().and_then(|env_var| {
428	                def.setup
429	                    .as_ref()
430	                    .and_then(|s| s.secret_name())
431	                    .map(|secret_name| (secret_name.to_string(), env_var.clone()))
432	            })
433	        })
434	        .collect();
435	    for (secret, env_var) in &dynamic_mappings {
436	        mappings.push((secret, env_var));
437	    }
438	
439	    let mut injected = HashMap::new();
440	
441	    for (secret_name, env_var) in mappings {
442	        match std::env::var(env_var) {
443	            Ok(val) if !val.is_empty() => continue,
444	            _ => {}
445	        }
446	        match secrets.get_decrypted(user_id, secret_name).await {
447	            Ok(decrypted) => {
448	                injected.insert(env_var.to_string(), decrypted.expose().to_string());
449	                tracing::debug!("Loaded secret '{}' for env var '{}'", secret_name, env_var);
450	            }
451	            Err(_) => {
452	                // Secret doesn't exist, that's fine
453	            }
454	        }
455	    }
456	
457	    inject_os_credential_store_tokens(&mut injected);
458	
459	    merge_injected_vars(injected);
460	}
461	
462	/// Load tokens from OS credential stores (no DB required).
463	///
464	/// Called unconditionally during startup — even when the encrypted secrets DB
465	/// is unavailable (no master key, no DB connection). This ensures OAuth tokens
466	/// from `claude login` (macOS Keychain / Linux credentials.json)
467	/// are available for config resolution.
468	pub fn inject_os_credentials() {
469	    let mut injected = HashMap::new();
470	    inject_os_credential_store_tokens(&mut injected);
471	    merge_injected_vars(injected);
472	}
473	
474	/// Merge new entries into the global injected-vars overlay.
475	///
476	/// New keys are inserted; existing keys are overwritten (later callers win,
477	/// e.g. fresh OS credential store tokens override stale DB copies).
478	fn merge_injected_vars(new_entries: HashMap<String, String>) {
479	    if new_entries.is_empty() {
480	        return;
481	    }
482	    match INJECTED_VARS.lock() {
483	        Ok(mut map) => map.extend(new_entries),
484	        Err(poisoned) => poisoned.into_inner().extend(new_entries),
485	    }
486	}
487	
488	/// Inject a single key-value pair into the overlay.
489	///
490	/// Used by the setup wizard to make credentials available to `optional_env()`
491	/// without calling `unsafe { std::env::set_var }`.
492	pub fn inject_single_var(key: &str, value: &str) {
493	    match INJECTED_VARS.lock() {
494	        Ok(mut map) => {
495	            map.insert(key.to_string(), value.to_string());
496	        }
497	        Err(poisoned) => {
498	            poisoned
499	                .into_inner()
500	                .insert(key.to_string(), value.to_string());
501	        }
502	    }
503	}
504	
505	/// Shared helper: extract tokens from OS credential stores into the overlay map.
506	fn inject_os_credential_store_tokens(injected: &mut HashMap<String, String>) {
507	    // Try the OS credential store for a fresh Anthropic OAuth token.
508	    // Tokens from `claude login` expire in 8-12h, so the DB copy may be stale.
509	    // A fresh extraction from macOS Keychain / Linux credentials.json wins
510	    // over the (possibly expired) copy stored in the encrypted secrets DB.
511	    if let Some(fresh) = crate::config::ClaudeCodeConfig::extract_oauth_token() {
512	        injected.insert("ANTHROPIC_OAUTH_TOKEN".to_string(), fresh);
513	        tracing::debug!("Refreshed ANTHROPIC_OAUTH_TOKEN from OS credential store");
514	    }
515	}
