42	    pub workspace: Option<Arc<Workspace>>,
43	    pub extension_manager: Option<Arc<ExtensionManager>>,
44	    pub mcp_session_manager: Arc<McpSessionManager>,
45	    pub mcp_process_manager: Arc<McpProcessManager>,
