47	    pub log_broadcaster: Arc<LogBroadcaster>,
48	    pub context_manager: Arc<ContextManager>,
49	    pub hooks: Arc<HookRegistry>,
50	    /// Shared thread/session manager used by the standard agent runtime.
51	    pub agent_session_manager: Arc<AgentSessionManager>,
52	    pub skill_registry: Option<Arc<std::sync::RwLock<SkillRegistry>>>,
