68	/// Builder that orchestrates the 5 mechanical init phases.
69	pub struct AppBuilder {
70	    config: Config,
71	    flags: AppBuilderFlags,
72	    toml_path: Option<std::path::PathBuf>,
73	    session: Arc<SessionManager>,
74	    log_broadcaster: Arc<LogBroadcaster>,
