76	    // Accumulated state
77	    db: Option<Arc<dyn Database>>,
78	    secrets_store: Option<Arc<dyn SecretsStore + Send + Sync>>,
79	
80	    // Test overrides
81	    llm_override: Option<Arc<dyn LlmProvider>>,
82	
83	    // Backend-specific handles needed by secrets store
84	    handles: Option<crate::db::DatabaseHandles>,
85	}
