123	    /// Phase 1: Initialize database backend.
124	    ///
125	    /// Creates the database connection, runs migrations, reloads config
126	    /// from DB, attaches DB to session manager, and cleans up stale jobs.
127	    pub async fn init_database(&mut self) -> Result<(), anyhow::Error> {
128	        if self.db.is_some() {
129	            tracing::debug!("Database already provided, skipping init_database()");
130	            return Ok(());
131	        }
132	
133	        if self.flags.no_db {
134	            tracing::warn!("Running without database connection");
135	            return Ok(());
136	        }
137	
138	        let (db, handles) = crate::db::connect_with_handles(&self.config.database)
139	            .await
140	            .map_err(|e| anyhow::anyhow!("{}", e))?;
141	        self.handles = Some(handles);
142	
143	        // Post-init: migrate disk config, reload config from DB, attach session, cleanup
144	        if let Err(e) =
145	            crate::bootstrap::migrate_disk_to_db(db.as_ref(), &self.config.owner_id).await
146	        {
147	            tracing::warn!("Disk-to-DB settings migration failed: {}", e);
148	        }
149	
150	        let toml_path = self.toml_path.as_deref();
151	        match Config::from_db_with_toml(db.as_ref(), &self.config.owner_id, toml_path).await {
152	            Ok(db_config) => {
153	                self.config = db_config;
154	                tracing::debug!("Configuration reloaded from database");
155	            }
156	            Err(e) => {
157	                tracing::warn!(
158	                    "Failed to reload config from DB, keeping env-based config: {}",
159	                    e
160	                );
161	            }
162	        }
163	
164	        self.session
165	            .attach_store(db.clone(), &self.config.owner_id)
166	            .await;
167	
168	        // Fire-and-forget housekeeping — no need to block startup.
169	        let db_cleanup = db.clone();
170	        tokio::spawn(async move {
171	            if let Err(e) = db_cleanup.cleanup_stale_sandbox_jobs().await {
172	                tracing::warn!("Failed to cleanup stale sandbox jobs: {}", e);
173	            }
174	        });
175	
176	        self.db = Some(db);
177	        Ok(())
178	    }
179	
180	    /// Phase 2: Create secrets store.
181	    ///
182	    /// Requires a master key and a backend-specific DB handle. After creating
183	    /// the store, injects any encrypted LLM API keys into the config overlay
184	    /// and re-resolves config.
185	    pub async fn init_secrets(&mut self) -> Result<(), anyhow::Error> {
186	        let master_key = match self.config.secrets.master_key() {
187	            Some(k) => k,
188	            None => {
189	                // No secrets DB available, but we can still load tokens from
190	                // OS credential stores (e.g., Anthropic OAuth via Claude Code's
191	                // macOS Keychain / Linux ~/.claude/.credentials.json).
192	                crate::config::inject_os_credentials();
193	
194	                // Consume unused handles
195	                self.handles.take();
196	
197	                // Re-resolve only the LLM config with OS credentials.
198	                let store: Option<&(dyn crate::db::SettingsStore + Sync)> =
199	                    self.db.as_ref().map(|db| db.as_ref() as _);
200	                let toml_path = self.toml_path.as_deref();
201	                let owner_id = self.config.owner_id.clone();
202	                if let Err(e) = self
203	                    .config
204	                    .re_resolve_llm(store, &owner_id, toml_path)
205	                    .await
206	                {
207	                    tracing::warn!(
208	                        "Failed to re-resolve LLM config after OS credential injection: {e}"
209	                    );
210	                }
211	
212	                return Ok(());
213	            }
214	        };
215	
216	        let crypto = match crate::secrets::SecretsCrypto::new(master_key.clone()) {
217	            Ok(c) => Arc::new(c),
218	            Err(e) => {
219	                tracing::warn!("Failed to initialize secrets crypto: {}", e);
220	                self.handles.take();
221	                return Ok(());
222	            }
223	        };
224	
225	        // Fallback covers the no-database path where `init_database` returned
226	        // early before populating `self.handles`.
227	        let empty_handles = crate::db::DatabaseHandles::default();
228	        let handles = self.handles.as_ref().unwrap_or(&empty_handles);
229	        let store = crate::secrets::create_secrets_store(crypto, handles);
230	
231	        if let Some(ref secrets) = store {
232	            // Inject LLM API keys from encrypted storage
233	            crate::config::inject_llm_keys_from_secrets(secrets.as_ref(), &self.config.owner_id)
234	                .await;
235	
236	            // Re-resolve only the LLM config with newly available keys.
237	            let store: Option<&(dyn crate::db::SettingsStore + Sync)> =
238	                self.db.as_ref().map(|db| db.as_ref() as _);
239	            let toml_path = self.toml_path.as_deref();
240	            let owner_id = self.config.owner_id.clone();
241	            if let Err(e) = self
242	                .config
243	                .re_resolve_llm(store, &owner_id, toml_path)
244	                .await
245	            {
246	                tracing::warn!("Failed to re-resolve LLM config after secret injection: {e}");
247	            }
248	        }
249	
250	        self.secrets_store = store;
251	        Ok(())
252	    }
253	
254	    /// Phase 3: Initialize LLM provider chain.
255	    ///
256	    /// Delegates to `build_provider_chain` which applies all decorators
257	    /// (retry, smart routing, failover, circuit breaker, response cache).
258	    #[allow(clippy::type_complexity)]
259	    pub async fn init_llm(
260	        &self,
261	    ) -> Result<
262	        (
263	            Arc<dyn LlmProvider>,
264	            Option<Arc<dyn LlmProvider>>,
265	            Option<Arc<RecordingLlm>>,
266	        ),
267	        anyhow::Error,
268	    > {
269	        let (llm, cheap_llm, recording_handle) =
270	            crate::llm::build_provider_chain(&self.config.llm, self.session.clone()).await?;
271	        Ok((llm, cheap_llm, recording_handle))
272	    }
