274	    /// Phase 4: Initialize safety, tools, embeddings, and workspace.
275	    pub async fn init_tools(
276	        &self,
277	        llm: &Arc<dyn LlmProvider>,
278	    ) -> Result<
279	        (
280	            Arc<SafetyLayer>,
281	            Arc<ToolRegistry>,
282	            Option<Arc<dyn EmbeddingProvider>>,
283	            Option<Arc<Workspace>>,
284	            Option<Arc<dyn crate::tools::SoftwareBuilder>>,
285	        ),
286	        anyhow::Error,
287	    > {
288	        let safety = Arc::new(SafetyLayer::new(&self.config.safety));
289	        tracing::debug!("Safety layer initialized");
290	
291	        // Initialize tool registry with credential injection support
292	        let credential_registry = Arc::new(SharedCredentialRegistry::new());
293	        let tools = if let Some(ref ss) = self.secrets_store {
294	            Arc::new(
295	                ToolRegistry::new()
296	                    .with_credentials(Arc::clone(&credential_registry), Arc::clone(ss)),
297	            )
298	        } else {
299	            Arc::new(ToolRegistry::new())
300	        };
301	        tools.register_builtin_tools();
302	        tools.register_tool_info();
303	
304	        if let Some(ref ss) = self.secrets_store {
305	            tools.register_secrets_tools(Arc::clone(ss));
306	        }
307	
308	        // Create embeddings provider using the unified method
309	        let embeddings = self
310	            .config
311	            .embeddings
312	            .create_provider(&self.config.llm.nearai.base_url, self.session.clone());
313	
314	        // Register memory tools if database is available
315	        let workspace_user_id = self.config.owner_id.as_str();
316	        let workspace = if let Some(ref db) = self.db {
317	            let emb_cache_config = EmbeddingCacheConfig {
318	                max_entries: self.config.embeddings.cache_size,
319	            };
320	            let mut ws = Workspace::new_with_db(workspace_user_id, db.clone())
321	                .with_search_config(&self.config.search);
322	
323	            if let Some(ref emb) = embeddings {
324	                ws = ws.with_embeddings_cached(emb.clone(), emb_cache_config.clone());
325	            }
326	
327	            // Wire workspace-level settings (read scopes, memory layers)
328	            if !self.config.workspace.read_scopes.is_empty() {
329	                ws = ws.with_additional_read_scopes(self.config.workspace.read_scopes.clone());
330	                tracing::info!(
331	                    user_id = workspace_user_id,
332	                    read_scopes = ?ws.read_user_ids(),
333	                    "Workspace configured with multi-scope reads"
334	                );
335	            }
336	            ws = ws.with_memory_layers(self.config.workspace.memory_layers.clone());
337	            let ws = Arc::new(ws);
338	
339	            // Detect multi-tenant mode: when GATEWAY_USER_TOKENS is configured,
340	            // each authenticated user needs their own workspace scope. Use
341	            // WorkspacePool (which implements WorkspaceResolver) to create
342	            // per-user workspaces on demand instead of sharing the startup
343	            // workspace across all users.
344	            let is_multi_tenant = self
345	                .config
346	                .channels
347	                .gateway
348	                .as_ref()
349	                .is_some_and(|gw| gw.user_tokens.is_some());
350	
351	            if is_multi_tenant {
352	                let pool = Arc::new(crate::channels::web::server::WorkspacePool::new(
353	                    Arc::clone(db),
354	                    embeddings.clone(),
355	                    emb_cache_config,
356	                    self.config.search.clone(),
357	                    self.config.workspace.clone(),
358	                ));
359	                tools.register_memory_tools_with_resolver(pool);
360	                tracing::info!(
361	                    "Memory tools configured with per-user workspace resolver (multi-tenant mode)"
362	                );
363	            } else {
364	                tools.register_memory_tools(Arc::clone(&ws));
365	            }
366	
367	            Some(ws)
368	        } else {
369	            None
370	        };
371	
372	        // Register image/vision tools if we have a workspace and LLM API credentials
373	        if workspace.is_some() {
374	            let (api_base, api_key_opt) = if let Some(ref provider) = self.config.llm.provider {
375	                (
376	                    provider.base_url.clone(),
377	                    provider.api_key.as_ref().map(|s| {
378	                        use secrecy::ExposeSecret;
379	                        s.expose_secret().to_string()
380	                    }),
381	                )
382	            } else {
383	                (
384	                    self.config.llm.nearai.base_url.clone(),
385	                    self.config.llm.nearai.api_key.as_ref().map(|s| {
386	                        use secrecy::ExposeSecret;
387	                        s.expose_secret().to_string()
388	                    }),
389	                )
390	            };
391	
392	            if let Some(api_key) = api_key_opt {
393	                // Check for image generation models
394	                let model_name = self
395	                    .config
396	                    .llm
397	                    .provider
398	                    .as_ref()
399	                    .map(|p| p.model.clone())
400	                    .unwrap_or_else(|| self.config.llm.nearai.model.clone());
401	                let models = vec![model_name.clone()];
402	                let gen_model = crate::llm::image_models::suggest_image_model(&models)
403	                    .unwrap_or("flux-1.1-pro")
404	                    .to_string();
405	                tools.register_image_tools(api_base.clone(), api_key.clone(), gen_model, None);
406	
407	                // Check for vision models
408	                let vision_model = crate::llm::vision_models::suggest_vision_model(&models)
409	                    .unwrap_or(&model_name)
410	                    .to_string();
411	                tools.register_vision_tools(api_base, api_key, vision_model, None);
412	            }
413	        }
414	
415	        // Register builder tool if enabled
416	        let builder = if self.config.builder.enabled
417	            && (self.config.agent.allow_local_tools || !self.config.sandbox.enabled)
418	        {
419	            let b = tools
420	                .register_builder_tool(llm.clone(), Some(self.config.builder.to_builder_config()))
421	                .await;
422	            tracing::debug!("Builder mode enabled");
423	            Some(b)
424	        } else {
425	            None
426	        };
427	
428	        Ok((safety, tools, embeddings, workspace, builder))
429	    }
