431	    /// Phase 5: Load WASM tools, MCP servers, and create extension manager.
432	    pub async fn init_extensions(
433	        &self,
434	        tools: &Arc<ToolRegistry>,
435	        hooks: &Arc<HookRegistry>,
436	    ) -> Result<
437	        (
438	            Arc<McpSessionManager>,
439	            Arc<McpProcessManager>,
440	            Option<Arc<WasmToolRuntime>>,
441	            Option<Arc<ExtensionManager>>,
442	            Vec<crate::extensions::RegistryEntry>,
443	            Vec<String>,
444	        ),
445	        anyhow::Error,
446	    > {
447	        use crate::tools::mcp::config::load_mcp_servers_from_db;
448	        use crate::tools::wasm::{WasmToolLoader, load_dev_tools};
449	
450	        let mcp_session_manager = Arc::new(McpSessionManager::new());
451	        let mcp_process_manager = Arc::new(McpProcessManager::new());
452	
453	        // Create WASM tool runtime eagerly so extensions installed after startup
454	        // (e.g. via the web UI) can still be activated. The tools directory is only
455	        // needed when loading modules, not for engine initialisation.
456	        let wasm_tool_runtime: Option<Arc<WasmToolRuntime>> = if self.config.wasm.enabled {
457	            WasmToolRuntime::new(self.config.wasm.to_runtime_config())
458	                .map(Arc::new)
459	                .map_err(|e| tracing::warn!("Failed to initialize WASM runtime: {}", e))
460	                .ok()
461	        } else {
462	            None
463	        };
464	
465	        // Load WASM tools and MCP servers concurrently
466	        let wasm_tools_future = {
467	            let wasm_tool_runtime = wasm_tool_runtime.clone();
468	            let secrets_store = self.secrets_store.clone();
469	            let tools = Arc::clone(tools);
470	            let wasm_config = self.config.wasm.clone();
471	            async move {
472	                let mut dev_loaded_tool_names: Vec<String> = Vec::new();
473	
474	                if let Some(ref runtime) = wasm_tool_runtime {
475	                    let mut loader = WasmToolLoader::new(Arc::clone(runtime), Arc::clone(&tools));
476	                    if let Some(ref secrets) = secrets_store {
477	                        loader = loader.with_secrets_store(Arc::clone(secrets));
478	                    }
479	
480	                    match loader.load_from_dir(&wasm_config.tools_dir).await {
481	                        Ok(results) => {
482	                            if !results.loaded.is_empty() {
483	                                tracing::debug!(
484	                                    "Loaded {} WASM tools from {}",
485	                                    results.loaded.len(),
486	                                    wasm_config.tools_dir.display()
487	                                );
488	                            }
489	                            for (path, err) in &results.errors {
490	                                tracing::warn!(
491	                                    "Failed to load WASM tool {}: {}",
492	                                    path.display(),
493	                                    err
494	                                );
495	                            }
496	                        }
497	                        Err(e) => {
498	                            tracing::warn!("Failed to scan WASM tools directory: {}", e);
499	                        }
500	                    }
501	
502	                    match load_dev_tools(&loader, &wasm_config.tools_dir).await {
503	                        Ok(results) => {
504	                            dev_loaded_tool_names.extend(results.loaded.iter().cloned());
505	                            if !dev_loaded_tool_names.is_empty() {
506	                                tracing::debug!(
507	                                    "Loaded {} dev WASM tools from build artifacts",
508	                                    dev_loaded_tool_names.len()
509	                                );
510	                            }
511	                        }
512	                        Err(e) => {
513	                            tracing::debug!("No dev WASM tools found: {}", e);
514	                        }
515	                    }
516	                }
517	
518	                dev_loaded_tool_names
519	            }
520	        };
521	
522	        let mcp_servers_future = {
523	            let secrets_store = self.secrets_store.clone();
524	            let db = self.db.clone();
525	            let tools = Arc::clone(tools);
526	            let mcp_sm = Arc::clone(&mcp_session_manager);
527	            let pm = Arc::clone(&mcp_process_manager);
528	            let owner_id = self.config.owner_id.clone();
529	            async move {
530	                let servers_result = if let Some(ref d) = db {
531	                    load_mcp_servers_from_db(d.as_ref(), &owner_id).await
532	                } else {
533	                    crate::tools::mcp::config::load_mcp_servers().await
534	                };
535	                match servers_result {
536	                    Ok(servers) => {
537	                        let enabled: Vec<_> = servers.enabled_servers().cloned().collect();
538	                        if !enabled.is_empty() {
539	                            tracing::debug!(
540	                                "Loading {} configured MCP server(s)...",
541	                                enabled.len()
542	                            );
543	                        }
544	
545	                        let mut join_set = tokio::task::JoinSet::new();
546	                        for server in enabled {
547	                            let mcp_sm = Arc::clone(&mcp_sm);
548	                            let secrets = secrets_store.clone();
549	                            let tools = Arc::clone(&tools);
550	                            let pm = Arc::clone(&pm);
551	                            let owner_id = owner_id.clone();
552	
553	                            join_set.spawn(async move {
554	                                let server_name = server.name.clone();
555	
556	                                let client = match crate::tools::mcp::create_client_from_config(
557	                                    server,
558	                                    &mcp_sm,
559	                                    &pm,
560	                                    secrets,
561	                                    &owner_id,
562	                                )
563	                                .await
564	                                {
565	                                    Ok(c) => c,
566	                                    Err(e) => {
567	                                        tracing::warn!(
568	                                            "Failed to create MCP client for '{}': {}",
569	                                            server_name,
570	                                            e
571	                                        );
572	                                        return None;
573	                                    }
574	                                };
575	
576	                                match client.list_tools().await {
577	                                    Ok(mcp_tools) => {
578	                                        let tool_count = mcp_tools.len();
579	                                        match client.create_tools().await {
580	                                            Ok(tool_impls) => {
581	                                                for tool in tool_impls {
582	                                                    tools.register(tool).await;
583	                                                }
584	                                                tracing::debug!(
585	                                                    "Loaded {} tools from MCP server '{}'",
586	                                                    tool_count,
587	                                                    server_name
588	                                                );
589	                                                return Some((
590	                                                    server_name,
591	                                                    Arc::new(client),
592	                                                ));
593	                                            }
594	                                            Err(e) => {
595	                                                tracing::warn!(
596	                                                    "Failed to create tools from MCP server '{}': {}",
597	                                                    server_name,
598	                                                    e
599	                                                );
600	                                            }
601	                                        }
602	                                    }
603	                                    Err(e) => {
604	                                        let err_str = e.to_string();
605	                                        if err_str.contains("401")
606	                                            || err_str.contains("authentication")
607	                                        {
608	                                            tracing::warn!(
609	                                                "MCP server '{}' requires authentication. \
610	                                                 Run: ironclaw mcp auth {}",
611	                                                server_name,
612	                                                server_name
613	                                            );
614	                                        } else {
615	                                            tracing::warn!(
616	                                                "Failed to connect to MCP server '{}': {}",
617	                                                server_name,
618	                                                e
619	                                            );
620	                                        }
621	                                    }
622	                                }
623	                                None
624	                            });
625	                        }
626	
627	                        let mut startup_clients = Vec::new();
628	                        while let Some(result) = join_set.join_next().await {
629	                            match result {
630	                                Ok(Some(client_pair)) => {
631	                                    startup_clients.push(client_pair);
632	                                }
633	                                Ok(None) => {}
634	                                Err(e) => {
635	                                    if e.is_panic() {
636	                                        tracing::error!("MCP server loading task panicked: {}", e);
637	                                    } else {
638	                                        tracing::warn!("MCP server loading task failed: {}", e);
639	                                    }
640	                                }
641	                            }
642	                        }
643	                        return startup_clients;
644	                    }
645	                    Err(e) => {
646	                        if matches!(
647	                            e,
648	                            crate::tools::mcp::config::ConfigError::InvalidConfig { .. }
649	                                | crate::tools::mcp::config::ConfigError::Json(_)
650	                        ) {
651	                            tracing::warn!(
652	                                "MCP server configuration is invalid: {}. \
653	                                 Fix or remove the corrupted config.",
654	                                e
655	                            );
656	                        } else {
657	                            tracing::debug!("No MCP servers configured ({})", e);
658	                        }
659	                    }
660	                }
661	                Vec::new()
662	            }
663	        };
664	
665	        let (dev_loaded_tool_names, startup_mcp_clients) =
666	            tokio::join!(wasm_tools_future, mcp_servers_future);
667	
668	        // Load registry catalog entries for extension discovery
669	        let mut catalog_entries = match crate::registry::RegistryCatalog::load_or_embedded() {
670	            Ok(catalog) => {
671	                let entries: Vec<_> = catalog
672	                    .all()
673	                    .iter()
674	                    .filter_map(|m| m.to_registry_entry())
675	                    .collect();
676	                tracing::debug!(
677	                    count = entries.len(),
678	                    "Loaded registry catalog entries for extension discovery"
679	                );
680	                entries
681	            }
682	            Err(e) => {
683	                tracing::warn!("Failed to load registry catalog: {}", e);
684	                Vec::new()
685	            }
686	        };
687	
688	        // Append builtin entries (e.g. channel-relay integrations) so they appear
689	        // in the web UI's available extensions list.
690	        let builtin = crate::extensions::registry::builtin_entries();
691	        for entry in builtin {
692	            if !catalog_entries.iter().any(|e| e.name == entry.name) {
693	                catalog_entries.push(entry);
694	            }
695	        }
696	
697	        // Create extension manager. Use ephemeral in-memory secrets if no
698	        // persistent store is configured (listing/install/activate still work).
699	        let ext_secrets: Arc<dyn crate::secrets::SecretsStore + Send + Sync> = if let Some(ref s) =
700	            self.secrets_store
701	        {
702	            Arc::clone(s)
703	        } else {
704	            use crate::secrets::{InMemorySecretsStore, SecretsCrypto};
705	            let ephemeral_key =
