954	/// Seed tool permission defaults into the database for every registered tool
955	/// that has no explicit user override yet.
956	///
957	/// This is called once at startup after the full tool registry is built.
958	/// It is idempotent: existing entries in `tool_permissions.*` are never touched.
959	async fn seed_tool_permissions(
960	    tools: &crate::tools::ToolRegistry,
961	    db: Option<&Arc<dyn Database>>,
962	    owner_id: &str,
963	) {
964	    use crate::tools::permissions::{TOOL_RISK_DEFAULTS, effective_permission};
965	
966	    let db = match db {
967	        Some(db) => db,
968	        None => {
969	            tracing::debug!("seed_tool_permissions: no database available, skipping");
970	            return;
971	        }
972	    };
973	
974	    // Load existing tool permission overrides from the DB.
975	    let db_map = match db.get_all_settings(owner_id).await {
976	        Ok(m) => m,
977	        Err(e) => {
978	            tracing::warn!("seed_tool_permissions: failed to load settings: {}", e);
979	            return;
980	        }
981	    };
982	    let existing = crate::settings::Settings::from_db_map(&db_map).tool_permissions;
983	
984	    let registered_names = tools.list().await;
985	    let mut seeded = 0u32;
986	
987	    for name in &registered_names {
988	        if existing.contains_key(name.as_str()) {
989	            // User has an explicit override — do not touch it.
990	            continue;
991	        }
992	
993	        // Only insert if the tool appears in the static defaults table.
994	        // Unknown/dynamic tools stay absent (they will fall back to AskEachTime
995	        // at runtime via effective_permission) to avoid polluting the DB.
996	        if TOOL_RISK_DEFAULTS.contains_key(name.as_str()) {
997	            let default_state = effective_permission(name, &existing);
998	            let json_value = match serde_json::to_value(default_state) {
999	                Ok(v) => v,
1000	                Err(e) => {
1001	                    tracing::warn!(
1002	                        "seed_tool_permissions: failed to serialize state for '{}': {}",
1003	                        name,
1004	                        e
1005	                    );
1006	                    continue;
1007	                }
1008	            };
1009	            if let Err(e) = db
1010	                .set_setting(owner_id, &format!("tool_permissions.{}", name), &json_value)
1011	                .await
1012	            {
1013	                tracing::warn!("seed_tool_permissions: failed to set '{}': {}", name, e);
1014	            } else {
1015	                seeded += 1;
1016	            }
1017	        }
1018	    }
1019	
1020	    if seeded > 0 {
1021	        tracing::debug!(
1022	            count = seeded,
1023	            "Seeded tool permission defaults into database"
1024	        );
1025	    }
1026	}
