38	/// Synchronous entry point. Loads `.env` files before the Tokio runtime
39	/// starts so that `std::env::set_var` is safe (no worker threads yet).
40	fn main() -> anyhow::Result<()> {
41	    // rustls 0.23 requires an explicit crypto provider installed process-wide.
42	    // tokio-xmpp uses rustls directly and panics without this.
43	    rustls::crypto::ring::default_provider()
44	        .install_default()
45	        .expect("failed to install rustls crypto provider");
46	
47	    let _ = dotenvy::dotenv();
48	    ironclaw::bootstrap::load_ironclaw_env();
49	
50	    let result = tokio::runtime::Builder::new_multi_thread()
51	        .enable_all()
52	        .build()?
53	        .block_on(async_main());
54	
55	    if let Err(ref e) = result {
56	        format_top_level_error(e);
57	    }
58	    result
59	}
