61	/// Format a top-level error with color and recovery hints.
62	fn format_top_level_error(err: &anyhow::Error) {
63	    use ironclaw::cli::fmt;
64	    let msg = format!("{err:#}");
65	
66	    eprintln!();
67	    eprintln!("  {}\u{2717}{} {}", fmt::error(), fmt::reset(), msg);
68	
69	    // Provide recovery hints for common errors
70	    let lower = msg.to_ascii_lowercase();
71	    let hint = if lower.contains("database_url")
72	        || lower.contains("database") && lower.contains("not set")
73	    {
74	        Some("run `ironclaw onboard` or set DATABASE_URL in .env")
75	    } else if lower.contains("connection refused") || lower.contains("connect error") {
76	        Some("check that the database server is running")
77	    } else if lower.contains("session") && lower.contains("not found") {
78	        Some("run `ironclaw onboard` to set up authentication")
79	    } else if lower.contains("secrets_master_key") {
80	        Some("run `ironclaw onboard` or set SECRETS_MASTER_KEY in .env")
81	    } else if lower.contains("already running") {
82	        Some("stop the other instance or remove the stale PID file")
83	    } else if lower.contains("onboard") {
84	        Some("run `ironclaw onboard` to complete setup")
85	    } else {
86	        None
87	    };
88	
89	    if let Some(hint_text) = hint {
90	        eprintln!("  {}hint:{} {}", fmt::dim(), fmt::reset(), hint_text,);
91	    }
92	    eprintln!();
93	}
