95	async fn async_main() -> anyhow::Result<()> {
96	    let cli = Cli::parse();
97	
98	    // Handle non-agent commands first (they don't need full setup)
99	    match &cli.command {
100	        Some(Command::Tool(tool_cmd)) => {
101	            init_cli_tracing();
102	            return run_tool_command(tool_cmd.clone()).await;
103	        }
104	        Some(Command::Config(config_cmd)) => {
105	            init_cli_tracing();
106	            return ironclaw::cli::run_config_command(config_cmd.clone()).await;
107	        }
108	        Some(Command::Registry(registry_cmd)) => {
109	            init_cli_tracing();
110	            return ironclaw::cli::run_registry_command(registry_cmd.clone()).await;
111	        }
112	        Some(Command::Channels(channels_cmd)) => {
113	            init_cli_tracing();
114	            return ironclaw::cli::run_channels_command(
115	                channels_cmd.clone(),
116	                cli.config.as_deref(),
117	            )
118	            .await;
119	        }
120	        Some(Command::Routines(routines_cmd)) => {
121	            init_cli_tracing();
122	            return ironclaw::cli::run_routines_cli(routines_cmd, cli.config.as_deref()).await;
123	        }
124	        Some(Command::Mcp(mcp_cmd)) => {
125	            init_cli_tracing();
126	            return run_mcp_command(*mcp_cmd.clone()).await;
127	        }
128	        Some(Command::Memory(mem_cmd)) => {
129	            init_cli_tracing();
130	            return ironclaw::cli::run_memory_command(mem_cmd).await;
131	        }
132	        Some(Command::Pairing(pairing_cmd)) => {
133	            init_cli_tracing();
134	            return run_pairing_command(pairing_cmd.clone()).map_err(|e| anyhow::anyhow!("{}", e));
135	        }
136	        Some(Command::Service(service_cmd)) => {
137	            init_cli_tracing();
