8	/// WASM sandbox configuration.
9	#[derive(Debug, Clone)]
10	pub struct WasmConfig {
11	    /// Whether WASM tool execution is enabled.
12	    pub enabled: bool,
13	    /// Directory containing installed WASM tools (default: ~/.ironclaw/tools/).
14	    pub tools_dir: PathBuf,
15	    /// Default memory limit in bytes (default: 10 MB).
16	    pub default_memory_limit: u64,
17	    /// Default execution timeout in seconds (default: 60).
18	    pub default_timeout_secs: u64,
19	    /// Default fuel limit for CPU metering (default: 10M).
20	    pub default_fuel_limit: u64,
21	    /// Whether to cache compiled modules.
22	    pub cache_compiled: bool,
23	    /// Directory for compiled module cache.
24	    pub cache_dir: Option<PathBuf>,
25	}
26	
27	impl Default for WasmConfig {
28	    fn default() -> Self {
29	        Self {
30	            enabled: true,
31	            tools_dir: default_tools_dir(),
32	            default_memory_limit: 10 * 1024 * 1024, // 10 MB
33	            default_timeout_secs: 60,
34	            default_fuel_limit: 10_000_000,
35	            cache_compiled: true,
36	            cache_dir: None,
37	        }
38	    }
39	}
40	
41	/// Get the default tools directory (~/.ironclaw/tools/).
42	fn default_tools_dir() -> PathBuf {
43	    ironclaw_base_dir().join("tools")
44	}
45	
46	impl WasmConfig {
47	    pub(crate) fn resolve(settings: &crate::settings::Settings) -> Result<Self, ConfigError> {
48	        let ws = &settings.wasm;
49	        Ok(Self {
50	            enabled: parse_bool_env("WASM_ENABLED", ws.enabled)?,
51	            tools_dir: optional_env("WASM_TOOLS_DIR")?
52	                .map(PathBuf::from)
53	                .or_else(|| ws.tools_dir.clone())
54	                .unwrap_or_else(default_tools_dir),
55	            default_memory_limit: parse_optional_env(
56	                "WASM_DEFAULT_MEMORY_LIMIT",
57	                ws.default_memory_limit,
58	            )?,
59	            default_timeout_secs: parse_optional_env(
60	                "WASM_DEFAULT_TIMEOUT_SECS",
61	                ws.default_timeout_secs,
62	            )?,
63	            default_fuel_limit: parse_optional_env(
64	                "WASM_DEFAULT_FUEL_LIMIT",
65	                ws.default_fuel_limit,
66	            )?,
67	            cache_compiled: parse_bool_env("WASM_CACHE_COMPILED", ws.cache_compiled)?,
68	            cache_dir: optional_env("WASM_CACHE_DIR")?
69	                .map(PathBuf::from)
70	                .or_else(|| ws.cache_dir.clone()),
71	        })
72	    }
73	
74	    /// Convert to WasmRuntimeConfig.
75	    pub fn to_runtime_config(&self) -> crate::tools::wasm::WasmRuntimeConfig {
76	        use crate::tools::wasm::{FuelConfig, ResourceLimits, WasmRuntimeConfig};
77	
78	        WasmRuntimeConfig {
79	            default_limits: ResourceLimits {
80	                memory_bytes: self.default_memory_limit,
81	                fuel: self.default_fuel_limit,
82	                timeout: Duration::from_secs(self.default_timeout_secs),
83	            },
84	            fuel_config: FuelConfig {
85	                initial_fuel: self.default_fuel_limit,
86	                enabled: true,
87	            },
88	            cache_compiled: self.cache_compiled,
89	            cache_dir: self.cache_dir.clone(),
90	            optimization_level: wasmtime::OptLevel::Speed,
91	        }
92	    }
93	}
