1284	                        .with_provider("xmpp".to_string()),
1285	                )
1286	                .await
1287	            {
1288	                tracing::warn!(error = %err, "Failed to persist migrated XMPP bridge token");
1289	            }
1290	        }
1291	    } else {
1292	        tracing::warn!(
1293	            "Native XMPP config detected, but no secrets store is available for migration"
1294	        );
1295	    }
1296	
