20	/// Result of WASM channel setup.
21	pub struct WasmChannelSetup {
22	    pub channels: Vec<(String, Box<dyn crate::channels::Channel>)>,
23	    pub channel_names: Vec<String>,
24	    pub webhook_routes: Option<axum::Router>,
25	    /// Runtime objects needed for hot-activation via ExtensionManager.
26	    pub wasm_channel_runtime: Arc<WasmChannelRuntime>,
27	    pub pairing_store: Arc<PairingStore>,
28	    pub wasm_channel_router: Arc<WasmChannelRouter>,
29	}
