110	/// Process a single loaded WASM channel: retrieve secrets, inject config,
111	/// register with the router, and set up signing keys and credentials.
112	async fn register_channel(
113	    loaded: LoadedChannel,
114	    config: &Config,
115	    secrets_store: &Option<Arc<dyn SecretsStore + Send + Sync>>,
116	    settings_store: Option<&Arc<dyn crate::db::SettingsStore>>,
117	    wasm_router: &Arc<WasmChannelRouter>,
118	) -> (String, Box<dyn crate::channels::Channel>) {
119	    let channel_name = loaded.name().to_string();
120	    tracing::debug!("Loaded WASM channel: {}", channel_name);
121	    let owner_actor_id = config
122	        .channels
123	        .wasm_channel_owner_ids
124	        .get(channel_name.as_str())
125	        .map(ToString::to_string);
126	
127	    let secret_name = loaded.webhook_secret_name();
128	    let sig_key_secret_name = loaded.signature_key_secret_name();
129	    let hmac_secret_name = loaded.hmac_secret_name();
130	
131	    let webhook_secret = if let Some(secrets) = secrets_store {
132	        secrets
133	            .get_decrypted(&config.owner_id, &secret_name)
134	            .await
135	            .ok()
136	            .map(|s| s.expose().to_string())
137	    } else {
138	        None
139	    };
140	
141	    let secret_header = loaded.webhook_secret_header().map(|s| s.to_string());
142	
143	    let webhook_path = format!("/webhook/{}", channel_name);
144	    let endpoints = vec![RegisteredEndpoint {
145	        channel_name: channel_name.clone(),
146	        path: webhook_path,
147	        methods: vec!["POST".to_string()],
148	        require_secret: webhook_secret.is_some(),
149	    }];
150	
151	    let channel_arc = Arc::new(loaded.channel.with_owner_actor_id(owner_actor_id.clone()));
152	
153	    // Inject runtime config (tunnel URL, webhook secret, owner_id).
154	    {
155	        let mut config_updates = std::collections::HashMap::new();
156	
157	        if let Some(ref tunnel_url) = config.tunnel.public_url {
158	            config_updates.insert(
159	                "tunnel_url".to_string(),
160	                serde_json::Value::String(tunnel_url.clone()),
161	            );
162	        }
163	
164	        if let Some(ref secret) = webhook_secret {
165	            config_updates.insert(
166	                "webhook_secret".to_string(),
167	                serde_json::Value::String(secret.clone()),
168	            );
169	        }
170	
171	        if let Some(&owner_id) = config
172	            .channels
173	            .wasm_channel_owner_ids
174	            .get(channel_name.as_str())
175	        {
176	            config_updates.insert("owner_id".to_string(), serde_json::json!(owner_id));
177	        }
178	
179	        if channel_name == TELEGRAM_CHANNEL_NAME
180	            && let Some(store) = settings_store
181	            && let Ok(Some(serde_json::Value::String(username))) = store
182	                .get_setting("default", &bot_username_setting_key(&channel_name))
183	                .await
184	            && !username.trim().is_empty()
185	        {
186	            config_updates.insert("bot_username".to_string(), serde_json::json!(username));
187	        }
188	
189	        config_updates.extend(
190	            load_channel_setup_field_overrides(
191	                settings_store,
192	                &config.owner_id,
193	                &channel_name,
194	                loaded.capabilities_file.as_ref(),
195	            )
196	            .await,
197	        );
