785	    /// Run all init phases in order and return the assembled components.
786	    pub async fn build_all(mut self) -> Result<AppComponents, anyhow::Error> {
787	        self.init_database().await?;
788	        self.init_secrets().await?;
789	
790	        // Post-init validation: backends with dedicated config (nearai, gemini_oauth,
791	        // bedrock, openai_codex) handle their own credential resolution. For registry-based
792	        // backends, fail early if no provider config was resolved.
793	        if !matches!(
794	            self.config.llm.backend.as_str(),
795	            "nearai" | "gemini_oauth" | "bedrock" | "openai_codex"
796	        ) && self.config.llm.provider.is_none()
797	        {
798	            let backend = &self.config.llm.backend;
799	            anyhow::bail!(
800	                "LLM_BACKEND={backend} is configured but no credentials were found. \
801	                 Set the appropriate API key environment variable or run the setup wizard."
802	            );
803	        }
804	
805	        let (llm, cheap_llm, recording_handle) = if let Some(llm) = self.llm_override.take() {
806	            (llm, None, None)
807	        } else {
808	            self.init_llm().await?
809	        };
810	        let (safety, tools, embeddings, workspace, builder) = self.init_tools(&llm).await?;
811	
812	        // Create hook registry early so runtime extension activation can register hooks.
813	        let hooks = Arc::new(HookRegistry::new());
814	        let agent_session_manager =
815	            Arc::new(AgentSessionManager::new().with_hooks(Arc::clone(&hooks)));
816	
817	        let (
818	            mcp_session_manager,
819	            mcp_process_manager,
820	            wasm_tool_runtime,
821	            extension_manager,
822	            catalog_entries,
823	            dev_loaded_tool_names,
824	        ) = self.init_extensions(&tools, &hooks).await?;
825	
826	        // Load bootstrap-completed flag from settings so that existing users
827	        // who already completed onboarding don't re-get bootstrap injection.
828	        if let Some(ref ws) = workspace {
829	            let toml_path = crate::settings::Settings::default_toml_path();
830	            if let Ok(Some(settings)) = crate::settings::Settings::load_toml(&toml_path)
831	                && settings.profile_onboarding_completed
832	            {
833	                ws.mark_bootstrap_completed();
834	            }
